-- 채용공고 URL 자동수집이 SPA(해시 라우팅) 채용페이지에서 실패하던 문제를
-- 조건부 헤드리스 브라우저(Playwright) 렌더링 폴백으로 해결한 과정과, 그 과정에서
-- 실제로 재현한 Playwright networkidle/content() 타이밍 버그, Alpine→glibc 전환,
-- Docker 레이어 용량 최적화(overlayfs chown copy-up, BuildKit bind-mount)까지 정리한
-- 스터디 노트. content_markdown 값은 이스케이프 문제를 원천 차단하기 위해 16진
-- 리터럴(X'...')로 기록한다 (V102~V107 컨벤션 준용).

INSERT INTO `study` (`slug`, `title`, `summary`, `content_markdown`, `status`, `category_id`, `learned_at`, `published_at`, `created_at`, `updated_at`)
VALUES (
  'headless-browser-spa-job-posting-scraping',
  'SPA 채용 페이지 자동수집을 위한 헤드리스 브라우저 도입기',
  'URL 프래그먼트(#/recruit)는 서버로 전송되지 않아 SPA 채용페이지 자동수집이 항상 실패하던 문제를, 텍스트 길이로 게이팅한 조건부 Playwright 헤드리스 렌더링 폴백으로 해결한 과정을 정리합니다. networkidle이 영영 안 오는 사이트, content() 타이밍 실패, Alpine의 musl 제약, Docker 레이어 용량 최적화까지 실제로 재현하며 만난 문제들을 다룹니다.',
  X'',
  'PUBLISHED',
  5,
  '2026-07-27',
  NOW(),
  NOW(), NOW()
);
SET @study_id = LAST_INSERT_ID();

INSERT INTO `study_tag` (`study_id`, `tag_id`) SELECT @study_id, `id` FROM `tag` WHERE `name` IN ('Docker', 'Playwright', 'Kubernetes');
INSERT INTO `study_skill` (`study_id`, `skill_id`) VALUES (@study_id, 31), (@study_id, 23), (@study_id, 35);

SELECT `id` INTO @docker_qemu_study_id FROM `study` WHERE `slug` = 'docker-multiarch-build-platform-native-compile-stage';
INSERT INTO `study_relation` (`source_study_id`, `target_study_id`, `relation_type`, `display_order`) VALUES
  (@study_id, @docker_qemu_study_id, 'RELATED', 0),
  (@docker_qemu_study_id, @study_id, 'RELATED', 0);
